"""A small linearizability checker for registers. Given: you do not edit this file.

This is the same idea as Lab 3 (Wing & Gong's search, with a memo of dead ends), cut down to what
Lab 7 needs and copied here so that this lab stands on its own. It handles read and write on a
register that starts as None, and it checks each key separately (linearizability is local: a
history is linearizable if and only if each key's sub-history is).

    Op(process, f, key, value, call, ret, indeterminate)
        f             "read" or "write"
        value         write: the value written;  read: the value it returned
        call, ret     invoke and completion times; ret is INF for an operation that timed out
        indeterminate True if it timed out: a write that may have taken effect at any time after
                      its call, or never. (Do not put timed-out reads in a history: they say nothing.)
"""
import sys
from collections import namedtuple

sys.setrecursionlimit(20000)
INF = float("inf")
Op = namedtuple("Op", "process f key value call ret indeterminate")


def check_register(ops):
    """ops: Ops on ONE key. Return a legal order (a list of Ops) or None."""
    ops = sorted(ops, key=lambda o: (o.call, o.process))
    n = len(ops)
    required = 0
    for i, o in enumerate(ops):
        if not o.indeterminate:
            required |= 1 << i
    dead = set()

    def search(done, state):
        if done & required == required:
            return []
        if (done, state) in dead:
            return None
        horizon = min(ops[i].ret for i in range(n) if required >> i & 1 and not done >> i & 1)
        for i in range(n):
            if done >> i & 1:
                continue
            o = ops[i]
            if o.call > horizon:
                break
            if o.f == "read" and o.value != state:
                continue
            rest = search(done | 1 << i, o.value if o.f == "write" else state)
            if rest is not None:
                return [o] + rest
        dead.add((done, state))
        return None

    return search(0, None)


def check_history(ops):
    """Check every key. Return None if all keys are linearizable, else the first bad key (sorted order)."""
    by_key = {}
    for o in ops:
        by_key.setdefault(o.key, []).append(o)
    for key in sorted(by_key):
        if check_register(by_key[key]) is None:
            return key
    return None
